441	            },
442	            "github_mirror": {
443	              "type": "string",
444	              "enum": [
445	                "bd_github_push_only",
446	                "none"
447	              ]
448	            },
449	            "board": {
450	              "type": "string",
451	              "description": "beads 束縛タスクの live 看板 UI 選択 (references/execution-tracker-contract.md §9 正本)。beads-kanban=doublej/strandkanban (旧称 beads-kanban、enum 値は後方互換のため旧名を維持。embedded bd で動作・clone+install で起動・外部依存・LICENSE要確認)。static-render=C05 render-graph-html のゼロ依存スナップショットのみ。omb-board=oh-my-beads 同梱の軽量 board (embedded 可)。none=看板なし。",
452	              "enum": [
453	                "beads-kanban",
454	                "static-render",
455	                "omb-board",
456	                "none"
457	              ]
458	            }
459	          }
460	        }
461	      },
462	      "allOf": [
463	        {
464	          "if": {
465	            "properties": {
466	              "mode": {
467	                "enum": [
468	                  "beads",
469	                  "both"
470	                ]
471	              }
472	            }
473	          },
474	          "then": {
475	            "required": [
476	              "beads"
477	            ]
478	          }
479	        }
480	      ]
481	    },
482	    "worktrees": {
483	      "type": "object",
484	      "additionalProperties": false,
485	      "required": [
486	        "enabled",
487	        "lease_ttl_seconds",
488	        "heartbeat_seconds",
489	        "coordination_store",
490	        "completion_write_branch",
491	        "dirty_worktree_policy"
492	      ],
493	      "properties": {
494	        "enabled": {
495	          "type": "boolean"
496	        },
497	        "lease_ttl_seconds": {
498	          "type": "integer",
499	          "minimum": 300,
500	          "maximum": 86400
501	        },
502	        "heartbeat_seconds": {
503	          "type": "integer",
504	          "minimum": 15,
505	          "maximum": 60
506	        },
507	        "coordination_store": {
508	          "const": "git_common_dir"
509	        },
510	        "completion_write_branch": {
511	          "const": "default"
512	        },
513	        "dirty_worktree_policy": {
514	          "const": "fail_closed"
515	        }
516	      }
517	    },
518	    "claude_hooks": {
519	      "type": "object",
520	      "additionalProperties": false,
521	      "required": [
522	        "source",
523	        "project_plugin_link",
524	        "session_start",
525	        "post_tool_reconcile",
526	        "task_completed_gate"
527	      ],
528	      "properties": {
529	        "source": {
530	          "type": "string",
531	          "enum": [
532	            "plugin",
533	            "project",
534	            "disabled"
535	          ]
536	        },
537	        "project_plugin_link": {
538	          "$ref": "#/$defs/repoRelative"
539	        },
540	        "session_start": {
541	          "type": "boolean"
542	        },
543	        "post_tool_reconcile": {
544	          "type": "boolean"
545	        },
546	        "task_completed_gate": {
547	          "type": "boolean"
548	        }
549	      }
550	    },
551	    "path_policy": {
552	      "type": "object",
553	      "additionalProperties": false,
554	      "required": [
555	        "authority",
556	        "stored_paths",
557	        "allow_outside_repository",
558	        "follow_content_symlinks_outside_repository"
559	      ],
560	      "properties": {
561	        "authority": {
562	          "const": "caller-repository"
563	        },
564	        "stored_paths": {
565	          "const": "repository-relative"
566	        },
567	        "allow_outside_repository": {
568	          "const": false
569	        },
570	        "follow_content_symlinks_outside_repository": {
571	          "const": false
572	        }
573	      }
574	    }
575	  },
576	  "allOf": [
577	    {
578	      "if": {
579	        "properties": {
580	          "execution_tracker": {
581	            "properties": {
582	              "mode": {
583	                "enum": [
584	                  "github",
585	                  "both"
586	                ]
587	              }
588	            }
589	          }
590	        }
591	      },
592	      "then": {
593	        "properties": {
594	          "github": {
595	            "properties": {
596	              "enabled": {
597	                "const": true
598	              }
599	            }
600	          }
601	        }
602	      }
603	    }
604	  ],
605	  "$defs": {
606	    "repoRelative": {
607	      "type": "string",
608	      "minLength": 1,
609	      "pattern": "^(?!/)(?!.*(?:^|/)\\.\\.(?:/|$)).+$"
610	    }
611	  }
612	}
